/**
 * The file-lifecycle corpus (plan 203, section 18): files a person can bring to Lolly,
 * built byte by byte so every one can be redistributed. It holds ordinary phone media,
 * files other programs wrote, and the inputs an intake path must survive: corrupt and
 * nested archives, decompression bombs, names and MIME types that lie, non-Latin and
 * very long names, colour-managed and HDR images and a multi-sheet workbook.
 *
 * Most fixtures are generated here, with Node's own zlib as the compressor, so no
 * shared Lolly writer can hide a reader mistake. The third-party files are the
 * unchanged copies already committed under tests/fixtures with their licences. The
 * README beside this file lists every fixture, its source and its licence;
 * `tests/file-intake-corpus.test.ts` runs each one through every intake path, and
 * `write.ts` saves the corpus as real files for device and installed-app checks.
 */
import { readFileSync } from 'node:fs';
import zlib from 'node:zlib';
import { readZip, srgbIccProfile } from '@lolly/engine';

/** What a fixture exercises. A fixture can belong to several families. */
export type Family =
  | 'ordinary' | 'third-party' | 'signed' | 'layered' | 'animated' | 'icc-hdr' | 'multi-sheet'
  | 'non-latin-name' | 'long-name' | 'misleading' | 'active-content' | 'corrupt-archive' | 'bomb'
  | 'oversize' | 'missing-dependency' | 'lolly';

/** How a builder asks for a large file without holding its bytes in memory. */
export interface BuildContext {
  /** A Blob of `size` bytes: `head`, then zeros, kept on disk as a sparse file. */
  sparse(name: string, head: Uint8Array, size: number): Promise<Blob>;
}

export interface Fixture {
  /** Stable id: the key in outcomes.json and the README table. */
  id: string;
  /** The file name exactly as an operating system would hand it over. */
  name: string;
  /** The MIME type the operating system supplies (blank when it supplies none). */
  type: string;
  families: Family[];
  /** What the bytes hold, in one sentence. */
  holds: string;
  /** Who made the bytes and the licence they travel under. */
  source: string;
  /** An input every path must refuse or contain within its limits. Measured first. */
  adversarial?: boolean;
  build(ctx: BuildContext): Promise<Blob>;
}

const GENERATED = 'Generated by corpus.ts, MPL-2.0.';
const enc = new TextEncoder();
const MiB = 1024 * 1024;

// ── byte helpers ──────────────────────────────────────────────────────────────

function concat(parts: readonly Uint8Array[]): Uint8Array {
  const out = new Uint8Array(parts.reduce((n, p) => n + p.length, 0));
  let at = 0;
  for (const p of parts) { out.set(p, at); at += p.length; }
  return out;
}
const crc32 = (bytes: Uint8Array, prev = 0): number => zlib.crc32(bytes, prev) >>> 0;
const blob = (bytes: Uint8Array): Blob => new Blob([bytes as BlobPart]);
const fixtureFile = (rel: string): Uint8Array => new Uint8Array(readFileSync(new URL(`../${rel}`, import.meta.url)));

/**
 * A raw DEFLATE stream of `mib` MiB of zeros, made from one fully flushed 1 MiB
 * block repeated, so a bomb costs a few hundred kilobytes to build rather than its
 * expanded size. A full flush resets the window, so the copies never reference
 * each other, and a final empty fixed block closes the stream.
 */
function zeroDeflate(mib: number): { data: Uint8Array; crc: number; size: number } {
  const zeros = new Uint8Array(MiB);
  const block = zlib.deflateRawSync(zeros, { level: 9, finishFlush: zlib.constants.Z_FULL_FLUSH });
  const data = new Uint8Array(block.length * mib + 2);
  let crc = 0;
  for (let i = 0; i < mib; i++) { data.set(block, i * block.length); crc = crc32(zeros, crc); }
  data.set([0x03, 0x00], block.length * mib);
  return { data, crc, size: mib * MiB };
}

// ── ZIP (hand-written, so corrupt variants are possible) ──────────────────────

interface ZipMember {
  name: string;
  /** The bytes as stored in the archive (compressed for method 8). */
  data: Uint8Array;
  method: 0 | 8;
  crc: number;
  /** The declared uncompressed size. */
  size: number;
  flags?: number;
}
const storedMember = (name: string, bytes: Uint8Array): ZipMember =>
  ({ name, data: bytes, method: 0, crc: crc32(bytes), size: bytes.length });
const deflatedMember = (name: string, bytes: Uint8Array): ZipMember =>
  ({ name, data: new Uint8Array(zlib.deflateRawSync(bytes)), method: 8, crc: crc32(bytes), size: bytes.length });

function zipOf(members: readonly ZipMember[], eocd: { count?: number } = {}): Uint8Array {
  const locals: Uint8Array[] = [];
  const centrals: Uint8Array[] = [];
  let offset = 0;
  for (const m of members) {
    const name = enc.encode(m.name);
    const flags = (m.flags ?? 0) | 0x0800;   // UTF-8 names
    const local = new Uint8Array(30 + name.length);
    const lv = new DataView(local.buffer);
    lv.setUint32(0, 0x04034b50, true); lv.setUint16(4, 20, true); lv.setUint16(6, flags, true);
    lv.setUint16(8, m.method, true); lv.setUint32(14, m.crc, true);
    lv.setUint32(18, m.data.length, true); lv.setUint32(22, m.size, true); lv.setUint16(26, name.length, true);
    local.set(name, 30);
    const central = new Uint8Array(46 + name.length);
    const cv = new DataView(central.buffer);
    cv.setUint32(0, 0x02014b50, true); cv.setUint16(4, 20, true); cv.setUint16(6, 20, true);
    cv.setUint16(8, flags, true); cv.setUint16(10, m.method, true); cv.setUint32(16, m.crc, true);
    cv.setUint32(20, m.data.length, true); cv.setUint32(24, m.size, true); cv.setUint16(28, name.length, true);
    cv.setUint32(42, offset, true);
    central.set(name, 46);
    locals.push(local, m.data);
    centrals.push(central);
    offset += local.length + m.data.length;
  }
  const directory = concat(centrals);
  const end = new Uint8Array(22);
  const ev = new DataView(end.buffer);
  const count = eocd.count ?? members.length;
  ev.setUint32(0, 0x06054b50, true); ev.setUint16(8, count, true); ev.setUint16(10, count, true);
  ev.setUint32(12, directory.length, true); ev.setUint32(16, offset, true);
  return concat([...locals, directory, end]);
}

// ── gzip and tar ──────────────────────────────────────────────────────────────

function gzipOf(deflated: Uint8Array, crc: number, size: number): Uint8Array {
  const trailer = new Uint8Array(8);
  const tv = new DataView(trailer.buffer);
  tv.setUint32(0, crc, true); tv.setUint32(4, size % 2 ** 32, true);
  return concat([Uint8Array.from([0x1f, 0x8b, 0x08, 0, 0, 0, 0, 0, 0, 0xff]), deflated, trailer]);
}

function tarOf(entries: ReadonlyArray<{ name: string; bytes: Uint8Array }>, opts: { badChecksum?: boolean } = {}): Uint8Array {
  const parts: Uint8Array[] = [];
  for (const { name, bytes } of entries) {
    const header = new Uint8Array(512);
    const put = (at: number, text: string): void => { header.set(enc.encode(text), at); };
    put(0, name);
    put(100, '0000644\0'); put(108, '0000000\0'); put(116, '0000000\0');
    put(124, `${bytes.length.toString(8).padStart(11, '0')}\0`);
    put(136, '00000000000\0');
    header.fill(0x20, 148, 156);
    header[156] = 0x30;
    put(257, 'ustar\0'); put(263, '00');
    let sum = header.reduce((n, b) => n + b, 0);
    if (opts.badChecksum) sum += 1;
    put(148, `${sum.toString(8).padStart(6, '0')}\0 `);
    parts.push(header, bytes, new Uint8Array((512 - (bytes.length % 512)) % 512));
  }
  parts.push(new Uint8Array(1024));
  return concat(parts);
}

// ── images ────────────────────────────────────────────────────────────────────

function pngChunk(type: string, data: Uint8Array): Uint8Array {
  const out = new Uint8Array(12 + data.length);
  const dv = new DataView(out.buffer);
  dv.setUint32(0, data.length);
  out.set(enc.encode(type), 4);
  out.set(data, 8);
  dv.setUint32(8 + data.length, crc32(out.subarray(4, 8 + data.length)));
  return out;
}
const u32be = (...values: number[]): Uint8Array => {
  const out = new Uint8Array(values.length * 4);
  values.forEach((v, i) => { new DataView(out.buffer).setUint32(i * 4, v); });
  return out;
};

/** A filter-0 PNG of solid `rgb`, with extra chunks between IHDR and IDAT. */
function pngOf(opts: { width: number; height: number; depth?: 8 | 16; rgb: [number, number, number]; before?: Uint8Array[]; after?: Uint8Array[] }): Uint8Array {
  const depth = opts.depth ?? 8;
  const bytesPerSample = depth / 8;
  const row = new Uint8Array(1 + opts.width * 3 * bytesPerSample);
  for (let x = 0; x < opts.width; x++) {
    opts.rgb.forEach((v, c) => {
      const at = 1 + (x * 3 + c) * bytesPerSample;
      if (depth === 16) { row[at] = v; row[at + 1] = v; } else row[at] = v;
    });
  }
  const raw = concat(Array.from({ length: opts.height }, () => row));
  const ihdr = new Uint8Array(13);
  new DataView(ihdr.buffer).setUint32(0, opts.width);
  new DataView(ihdr.buffer).setUint32(4, opts.height);
  ihdr[8] = depth; ihdr[9] = 2;
  return concat([
    Uint8Array.from([137, 80, 78, 71, 13, 10, 26, 10]),
    pngChunk('IHDR', ihdr),
    ...(opts.before ?? []),
    pngChunk('IDAT', new Uint8Array(zlib.deflateSync(raw))),
    ...(opts.after ?? []),
    pngChunk('IEND', new Uint8Array(0)),
  ]);
}

/** A two-frame 2x2 APNG: red, then blue, half a second each, looping. */
function apngOf(): Uint8Array {
  const frame = (rgb: [number, number, number]): Uint8Array => {
    const row = Uint8Array.from([0, ...rgb, ...rgb]);
    return new Uint8Array(zlib.deflateSync(concat([row, row])));
  };
  const fctl = (seq: number): Uint8Array => {
    const d = new Uint8Array(26);
    const v = new DataView(d.buffer);
    v.setUint32(0, seq); v.setUint32(4, 2); v.setUint32(8, 2); v.setUint16(20, 1); v.setUint16(22, 2);
    return pngChunk('fcTL', d);
  };
  const ihdr = new Uint8Array(13);
  new DataView(ihdr.buffer).setUint32(0, 2);
  new DataView(ihdr.buffer).setUint32(4, 2);
  ihdr[8] = 8; ihdr[9] = 2;
  return concat([
    Uint8Array.from([137, 80, 78, 71, 13, 10, 26, 10]),
    pngChunk('IHDR', ihdr),
    pngChunk('acTL', u32be(2, 0)),
    fctl(0),
    pngChunk('IDAT', frame([255, 0, 0])),
    fctl(1),
    pngChunk('fdAT', concat([u32be(2), frame([0, 0, 255])])),
    pngChunk('IEND', new Uint8Array(0)),
  ]);
}

/**
 * The smallest complete baseline JPEG: one 8x8 grey block (every coefficient zero),
 * with an EXIF block that holds a camera make, orientation 6 (the phone was turned)
 * and GPS coordinates, as a phone photo does.
 */
function phoneJpeg(): Uint8Array {
  const tiff = new Uint8Array(160);
  const v = new DataView(tiff.buffer);
  tiff.set(enc.encode('II'), 0); v.setUint16(2, 42, true); v.setUint32(4, 8, true);
  const entry = (at: number, tag: number, type: number, count: number, value: number): void => {
    v.setUint16(at, tag, true); v.setUint16(at + 2, type, true); v.setUint32(at + 4, count, true); v.setUint32(at + 8, value, true);
  };
  v.setUint16(8, 3, true);
  entry(10, 0x010f, 2, 8, 50);          // Make, out of line
  entry(22, 0x0112, 3, 1, 6);           // Orientation 6
  entry(34, 0x8825, 4, 1, 58);          // GPS IFD
  v.setUint32(46, 0, true);
  tiff.set(enc.encode('Corpus\0\0'), 50);
  v.setUint16(58, 2, true);
  entry(60, 0x0001, 2, 2, 0x4e);        // N
  entry(72, 0x0002, 5, 3, 112);         // latitude, out of line
  v.setUint32(84, 0, true);
  [51, 1, 30, 1, 0, 1].forEach((n, i) => { v.setUint32(112 + i * 4, n, true); });
  const exif = concat([enc.encode('Exif\0\0'), tiff]);
  const segment = (marker: number, body: Uint8Array): Uint8Array =>
    concat([Uint8Array.from([0xff, marker, (body.length + 2) >> 8, (body.length + 2) & 0xff]), body]);
  return concat([
    Uint8Array.from([0xff, 0xd8]),
    segment(0xe1, exif),
    segment(0xdb, concat([Uint8Array.from([0]), new Uint8Array(64).fill(1)])),
    segment(0xc0, Uint8Array.from([8, 0, 8, 0, 8, 1, 1, 0x11, 0])),
    segment(0xc4, concat([Uint8Array.from([0x00, 1]), new Uint8Array(15), Uint8Array.from([0])])),
    segment(0xc4, concat([Uint8Array.from([0x10, 1]), new Uint8Array(15), Uint8Array.from([0])])),
    segment(0xda, Uint8Array.from([1, 1, 0x00, 0, 63, 0])),
    Uint8Array.from([0x3f, 0xff, 0xd9]),
  ]);
}

// ── documents ─────────────────────────────────────────────────────────────────

/** A one-page PDF with real cross-reference offsets. */
function pdfOf(text: string): Uint8Array {
  const stream = `BT /F1 18 Tf 36 96 Td (${text}) Tj ET`;
  const objects = [
    '<< /Type /Catalog /Pages 2 0 R >>',
    '<< /Type /Pages /Kids [3 0 R] /Count 1 >>',
    '<< /Type /Page /Parent 2 0 R /MediaBox [0 0 300 144] /Contents 4 0 R /Resources << /Font << /F1 5 0 R >> >> >>',
    `<< /Length ${stream.length} >>\nstream\n${stream}\nendstream`,
    '<< /Type /Font /Subtype /Type1 /BaseFont /Helvetica >>',
  ];
  let body = '%PDF-1.4\n';
  const offsets: number[] = [];
  objects.forEach((o, i) => { offsets.push(body.length); body += `${i + 1} 0 obj\n${o}\nendobj\n`; });
  const xref = body.length;
  body += `xref\n0 ${objects.length + 1}\n0000000000 65535 f \n${offsets.map((o) => `${String(o).padStart(10, '0')} 00000 n \n`).join('')}`;
  body += `trailer\n<< /Size ${objects.length + 1} /Root 1 0 R >>\nstartxref\n${xref}\n%%EOF\n`;
  return enc.encode(body);
}

const xml = (s: string): Uint8Array => enc.encode(`<?xml version="1.0" encoding="UTF-8" standalone="yes"?>\n${s}`);
const SHEET_NS = 'http://schemas.openxmlformats.org/spreadsheetml/2006/main';
const REL_NS = 'http://schemas.openxmlformats.org/officeDocument/2006/relationships';

/**
 * A three-sheet workbook written part by part from the OOXML schema, not by Lolly's
 * writer: shared strings on the first sheet, inline strings on the second, a hidden
 * third sheet, and sheet names in three scripts.
 */
function workbookOf(): Uint8Array {
  const sheets = [
    { name: 'Summary', rows: '<row r="1"><c r="A1" t="s"><v>0</v></c><c r="B1" t="s"><v>1</v></c></row><row r="2"><c r="A2" t="s"><v>2</v></c><c r="B2"><v>1250.5</v></c></row>' },
    { name: '数据 2026', rows: '<row r="1"><c r="A1" t="inlineStr"><is><t>月份</t></is></c><c r="B1" t="inlineStr"><is><t>金额</t></is></c></row><row r="2"><c r="A2" t="inlineStr"><is><t>十月</t></is></c><c r="B2"><v>88</v></c></row>' },
    { name: 'Résumé', hidden: true, rows: '<row r="1"><c r="A1" t="inlineStr"><is><t>Notes cachées</t></is></c></row>' },
  ];
  const members: ZipMember[] = [
    deflatedMember('[Content_Types].xml', xml(`<Types xmlns="http://schemas.openxmlformats.org/package/2006/content-types"><Default Extension="rels" ContentType="application/vnd.openxmlformats-package.relationships+xml"/><Default Extension="xml" ContentType="application/xml"/><Override PartName="/xl/workbook.xml" ContentType="application/vnd.openxmlformats-officedocument.spreadsheetml.sheet.main+xml"/>${sheets.map((_, i) => `<Override PartName="/xl/worksheets/sheet${i + 1}.xml" ContentType="application/vnd.openxmlformats-officedocument.spreadsheetml.worksheet+xml"/>`).join('')}<Override PartName="/xl/sharedStrings.xml" ContentType="application/vnd.openxmlformats-officedocument.spreadsheetml.sharedStrings+xml"/></Types>`)),
    deflatedMember('_rels/.rels', xml(`<Relationships xmlns="http://schemas.openxmlformats.org/package/2006/relationships"><Relationship Id="rId1" Type="${REL_NS}/officeDocument" Target="xl/workbook.xml"/></Relationships>`)),
    deflatedMember('xl/workbook.xml', xml(`<workbook xmlns="${SHEET_NS}" xmlns:r="${REL_NS}"><sheets>${sheets.map((s, i) => `<sheet name="${s.name}" sheetId="${i + 1}"${s.hidden ? ' state="hidden"' : ''} r:id="rId${i + 1}"/>`).join('')}</sheets></workbook>`)),
    deflatedMember('xl/_rels/workbook.xml.rels', xml(`<Relationships xmlns="http://schemas.openxmlformats.org/package/2006/relationships">${sheets.map((_, i) => `<Relationship Id="rId${i + 1}" Type="${REL_NS}/worksheet" Target="worksheets/sheet${i + 1}.xml"/>`).join('')}<Relationship Id="rId9" Type="${REL_NS}/sharedStrings" Target="sharedStrings.xml"/></Relationships>`)),
    deflatedMember('xl/sharedStrings.xml', xml(`<sst xmlns="${SHEET_NS}" count="3" uniqueCount="3"><si><t>Item</t></si><si><t>Cost</t></si><si><t>Café ☕</t></si></sst>`)),
    ...sheets.map((s, i) => deflatedMember(`xl/worksheets/sheet${i + 1}.xml`, xml(`<worksheet xmlns="${SHEET_NS}"><sheetData>${s.rows}</sheetData></worksheet>`))),
  ];
  return zipOf(members);
}

