// ── .lolly files ──────────────────────────────────────────────────────────────

const tinyPng = (): Uint8Array => pngOf({ width: 1, height: 1, rgb: [224, 69, 123] });

/**
 * A shared design built by the format's own writer, optionally leaving one upload's
 * bytes out. The writer stamps the export time into the manifest, the README and the
 * ZIP headers, so the parts are re-packed in order with that time fixed: the manifest
 * and README sit outside the integrity map, and every build is byte-identical.
 */
async function lollyOf(opts: { missing?: boolean } = {}): Promise<Uint8Array> {
  const { buildLollyFile } = await import('../../../shells/web/src/lib/lolly-pack.ts');
  const id = 'user/upload/1760000000000-photo.png';
  const record = { id, type: 'raster', format: 'png', version: 'v1', meta: { name: 'Café 写真.png' }, blob: new Blob([tinyPng() as BlobPart], { type: 'image/png' }) };
  const built = await buildLollyFile({
    toolId: 'qr-code',
    session: { __toolId: 'qr-code', __label: 'Café menu 写真', url: 'https://example.org/menu', logo: { id, source: 'user', type: 'raster', format: 'png', version: 'v1', url: '' } },
    userAssets: opts.missing ? [] : [record as never],
    creator: { createdWith: 'Lolly', createdAt: FIXED_TIME },
  });
  const stamped = built.manifest.exportedAt;
  return zipOf(readZip(new Uint8Array(await built.blob.arrayBuffer())).map(({ name, bytes }) => {
    if (name !== 'manifest.json' && name !== 'lolly.txt') return deflatedMember(name, bytes);
    return deflatedMember(name, enc.encode(new TextDecoder().decode(bytes).split(stamped).join(FIXED_TIME)));
  }));
}
const FIXED_TIME = '2026-10-16T12:00:00.000Z';

