/** The fixture with this id; throws on a typo so a test never silently skips one. */
export function fixture(id: string): Fixture {
  const found = CORPUS.find((f) => f.id === id);
  if (!found) throw new Error(`no corpus fixture "${id}"`);
  return found;
}
